#define rot(x) mat2(cos(x+vec4(0,11,33,0)))
//formula for creating colors;
#define H(h)  ( cos( h/2. + 5.1*vec3(2,3,4) )*.7 + .5 )
#define H2(h) ( cos( h*h/2. + vec3(1,2,0) )*.7 + .2 )
//formula for mapping scale factor 
#define M(c)  log(1.+c)
#define R iResolution
#define C(x) x = x>1. ? x=2.-x : (x<-1. ? -2.-x : x)

void mainImage0( out vec4 O, vec2 U) {

    O = vec4(0);    
    vec3 c=vec3(0);
    vec4 rd = normalize( vec4(U-.5*R.xy, .8*R.y, R.y))*200.; 
    float sc,dotp,totdist=0.,t=mod(iTime,120.);  
    float iters = mod(iTime,12.)<6.?6.:4.;

    float depth = 2. + clamp( 8.*sin(iTime/2.), -.5, 3.);

    for (float i=0.; i<100.; i++) {       
        vec4 p = vec4( rd*totdist);            
        p.xyz += vec3(0,depth,t);        
        p.yzw = p.xyz;
        p.zw *= rot(1.57);
        p.xz = cos(p.xz);

        p.xw *= rot(iTime/10.);

        sc = 1.; 
        for (float j=0.; j<3.; j++) {

            C(p.x); C(p.y); C(p.z); C(p.w);  
            p *= .55;
            p -= .5*p;
            dotp = max(1./dot(p.xy,p.xy),.1);
            sc *= dotp;
            p = 1.7 *p * dotp;                    
        }

        float dist = abs( length(p.zw)-.13)/sc ; 
        float stepsize = dist/40. ;     
        totdist += stepsize;                 

        c += (
               .015* H2(  atan( p.z, p.w ))  
             + .012* H(M(sc))
             ) * exp(-i*i*stepsize*stepsize*300.);
    }

    c = 1. - exp(-c*c);
    c *= exp(-totdist);
    O = ( vec4(c,0) );

}

//FabriceNeyret2 antialiasing trick
void mainImage(out vec4 O, vec2 U) {
    mainImage0(O,U);
    if ( fwidth(length(O)) > .001 ) {  // difference threshold between neighbor pixels
        vec4 o;
        for (int k=0; k < 9; k+= k==3?2:1 )
          { mainImage0(o,U+vec2(k%3-1,k/3-1)/3.); O += o; }
        O /= 9.;
        //O.b++; // uncomment to see where the oversampling occurs
    }
}
